    { l := some q, var := none, stk := update (update S rev []) main ((S rev).reverseAux (S main)) }

Turing.PartrecToTM2.move₂_ok.code:
Turing.PartrecToTM2.move₂_ok {p : Γ' → Bool} {k₁ k₂ : K'} {q : Λ'} {s : Option Γ'} {L₁ : List Γ'} {o : Option Γ'}
  {L₂ : List Γ'} {S : K' → List Γ'} (h₁ : k₁ ≠ rev ∧ k₂ ≠ rev ∧ k₁ ≠ k₂) (h₂ : S rev = [])
  (e : splitAtPred p (S k₁) = (L₁, o, L₂)) :
  Reaches₁ (TM2.step tr) { l := some (move₂ p k₁ k₂ q), var := s, stk := S }
    { l := some q, var := none, stk := update (update S k₁ (o.elim id List.cons L₂)) k₂ (L₁ ++ S k₂) }

