Turing.PartrecToTM2.pred_ok.code:
Turing.PartrecToTM2.pred_ok (q₁ q₂ : Λ') (s : Option Γ') (v : List ℕ) (c d : List Γ') :
  ∃ s',
    Reaches₁ (TM2.step tr) { l := some (q₁.pred q₂), var := s, stk := elim (trList v) [] c d }
      (Nat.rec { l := some q₁, var := s', stk := elim (trList v.tail) [] c d }
        (fun n x => { l := some q₂, var := s', stk := elim (trList (n :: v.tail)) [] c d }) v.headI)

